"""Replace the end-of-lesson checks with scenario questions that have four plausible options of similar length.
The correct answer is placed at a balanced position, so it cannot be guessed from its place or its length.
One-off tool: a few option texts were polished by hand afterwards, so do not re-run it over the current content."""
import json
import random
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
F = Path(__file__).resolve().parents[1] / "app" / "content" / "lessons.json"

# id: (question, correct, [three wrong options], explanation)
Q = {
 "journey": ("A returning visitor opens shop.com again. Which step can the browser skip without asking any server, because the answer is stored locally?", "The DNS lookup, because the IP address was cached until its TTL ends", ["Opening a connection, because connections are kept open forever", "Logging in, because the server remembers every browser", "The HTTP request, because pages are always cached for a year"], "DNS answers are cached by the browser and the operating system for the length of their TTL. Connections do close, and the server still has to answer the request."),
 "net": ("A live video call loses a packet. Why is UDP usually a better fit than TCP here?", "A late packet is useless, so dropping it beats stalling everything to resend it", ["UDP encrypts the stream, which TCP cannot do", "UDP guarantees every packet arrives in the right order", "UDP keeps working when the Wi-Fi connection is down"], "TCP retransmits and delivers in order, so one lost packet delays everything behind it. A call would rather skip a moment than wait."),
 "os": ("Two threads in one process update a shared counter and some updates vanish. Why cannot two separate processes damage each other's memory this way?", "Each process has its own memory, while threads in one process share it", ["Processes run on different CPUs, so they never overlap in time", "The operating system locks a variable whenever it changes", "Processes run more slowly, which hides the timing problem"], "Threads share one address space, so unsynchronised writes can interleave. Processes are isolated from each other by the operating system."),
 "numbers": ("A request passes through three services in a chain, each 99.9% available. About what is the overall availability?", "About 99.7%, because the availabilities multiply", ["99.9%, since all three services have the same target", "99.99%, because three checks make failure less likely", "About 97%, because each service loses a full percent"], "0.999 x 0.999 x 0.999 is about 0.997. Every dependency in series lowers the total."),
 "estimate": ("A service receives 100 million requests a day. About how many requests per second is that on average?", "About 1,200", ["About 100, dividing by a million", "About 12,000", "About 120,000"], "A day has 86,400 seconds, and 100,000,000 / 86,400 is about 1,157. Peak is usually two to three times higher."),
 "req": ("You are designing a post's like counter and a bank balance. Which pairing of consistency needs is sensible?", "The counter can be eventually consistent, the balance needs strong consistency", ["Both need strong consistency, because wrong numbers lose trust", "Both can be eventually consistent, since users refresh anyway", "The counter needs strong consistency, the balance can be eventual"], "A like count that is briefly off is harmless, so favour availability and speed. A wrong balance is worse than a short error."),
 "lb": ("Why should app servers behind a load balancer keep no user state on their own disk or memory?", "Any server can handle any request, so servers can be added or lost freely", ["It lets the load balancer skip health checks", "It makes every request run faster on the server", "It removes the need for a database"], "Stateless servers are interchangeable. That is what lets the load balancer spread traffic and survive a failure."),
 "cache": ("A very popular cache entry expires and thousands of requests reach the database at once. What is this, and what helps?", "A cache stampede; single-flight locking and TTL jitter help", ["Cache penetration; a Bloom filter for missing keys helps", "A hot key; replicating the entry to more nodes helps", "A write-back failure; flushing the cache more often helps"], "Many concurrent misses on one expired key is a stampede. Penetration is requests for keys that do not exist, and a hot key is steady heavy traffic on one key."),
 "cdn": ("You ship a new JavaScript file but users still get the old one from the CDN. What is the cleanest fix that needs no purge?", "Put a content hash in the file name, so each release has a new URL", ["Set the cache lifetime to a few seconds for every file", "Serve the file from the app server and skip the CDN", "Ask users to clear their browser cache after each release"], "A new hash is a new URL, so nothing stale is ever requested. Short lifetimes throw away the benefit of the CDN."),
 "queue": ("A queue delivers each message at least once. What property must a consumer have?", "Idempotent: handling a message twice has the same effect as once", ["Synchronous: it must finish before the next message arrives", "Stateless: it must remember nothing between messages", "Ordered: it must process messages in the order they were sent"], "A message can arrive twice, for example when a worker crashes before acknowledging. The handler must tolerate that."),
 "db": ("An app needs orders, customers and payments, with transactions across them. What is the sensible default store?", "A relational database such as PostgreSQL", ["A key-value store, because lookups are fast", "A graph database, because the data is related", "A search engine, because users will filter orders"], "Related data with transactional needs is what relational databases are built for. Move a workload elsewhere only when you can name the limit you hit."),
 "shard": ("Why is consistent hashing better than hash(key) mod N when you add a shard?", "Only about 1/N of the keys move, instead of nearly all of them", ["Each key's hash is faster to compute", "Every shard ends up with exactly the same number of keys", "It removes the need to replicate shards"], "With mod N, changing N changes the home of almost every key. On a ring a new node only takes over a slice."),
 "search": ("Why is a word search on an inverted index fast, even across millions of documents?", "The word-to-documents lists are built ahead of time, so a query combines short lists", ["It scans every document, but with many threads", "It keeps the entire database in memory", "It only searches the newest documents"], "The expensive work of splitting text and listing which documents hold each word happens at index time, not at query time."),
 "repl": ("With 5 replicas, which write and read quorum sizes guarantee that a read overlaps the latest write?", "W = 3 and R = 3, because R + W is greater than N", ["W = 2 and R = 3, because reads check a majority", "W = 3 and R = 2, because writes reach a majority", "W = 2 and R = 2, because that is about half"], "R + W must exceed N. 3 + 3 = 6 is more than 5, but 2 + 3 = 5 and 3 + 2 = 5 are not."),
 "engines": ("Which storage engine usually suits a very high rate of writes, and why?", "An LSM-tree, because it turns random writes into sequential appends", ["A B-tree, because it updates pages in place with no extra work", "A B-tree, because its reads are fastest, so writes finish sooner", "An LSM-tree, because it never needs any background work"], "LSM-trees buffer writes in memory and flush sorted files, paying later with compaction. B-trees do random in-place page updates."),
 "tx": ("Two requests each read a balance of 100, add 10 in application code and write it back. The final balance is 110. What happened?", "A lost update: one write overwrote the other", ["A dirty read: one request saw uncommitted data", "A phantom read: a new row appeared during a query", "Write skew: two requests broke a rule across different rows"], "Both read 100 and both wrote 110, so one deposit vanished. Do the addition inside the database in one atomic statement."),
 "model": ("A product page always shows the product plus its five photos, and the photos never change on their own. What suits a document store?", "Embed the photos inside the product document", ["Keep the photos in their own collection and join on read", "Store each photo as a document in a second database", "Keep only photo IDs and fetch each photo with its own call"], "Small child data that is always read with its parent is a good fit for embedding. It needs one lookup and no joins."),
 "serial": ("Which change keeps old readers of a Protobuf message working?", "Adding a new optional field with a new field number", ["Reusing the number of a removed field for a new field", "Changing a field's type from a number to a string", "Deleting a field and renumbering the ones after it"], "Old readers ignore fields they do not know. Reusing or renumbering fields makes old data decode as the wrong thing."),
 "datatypes": ("A shop uses PostgreSQL plus a search index. Where should the source of truth live?", "In PostgreSQL, with the index rebuilt from it when needed", ["In the search index, because it already has every field", "In both, written separately by the application", "In the cache, because it is the fastest store"], "An index is derived data and can be rebuilt. Writing to two places separately invites drift between them."),
 "cap": ("During a network partition, what does a CP system do?", "It refuses some requests on the minority side, to stay consistent", ["It accepts writes on both sides and merges them later", "It switches to eventual consistency and keeps answering", "It shuts down every node until the network is repaired"], "A CP system gives up availability on the side that cannot reach a majority rather than let copies diverge."),
 "consensus": ("A 5-node Raft cluster loses two nodes. What happens?", "It keeps working, because 3 of 5 is still a majority", ["It stops accepting writes until a node returns", "It keeps serving reads but refuses every write", "It elects two leaders, one for each group"], "Raft needs a majority. With N = 2f + 1 nodes it tolerates f failures, so five nodes tolerate two."),
 "clocks": ("Two writes to one key came from different servers. Which tool can tell whether they were concurrent?", "Vector clocks, because incomparable vectors mean neither came first", ["Wall-clock timestamps, because the later time is the newer write", "Lamport timestamps, because equal values mean concurrent", "The order in which the writes reached the database"], "Lamport timestamps give a consistent order but cannot show concurrency. Wall clocks can be wrong by the skew between servers."),
 "api": ("A client times out on a payment request and retries. How do you avoid charging twice?", "Require an idempotency key and return the saved result for repeats", ["Reject every retry with an error", "Raise the timeout so retries become rare", "Charge twice and refund duplicates every night"], "The server stores the result under the key. A retry with the same key gets the same answer without a second charge."),
 "apistyles": ("Which API style best suits fast, typed calls between your own backend services?", "gRPC, with compact Protobuf messages and generated clients", ["GraphQL, because clients choose their own fields", "REST, because every browser can call it", "Server-sent events, because they keep a connection open"], "gRPC is compact, fast and gives typed clients, which suits internal calls. REST and GraphQL suit public and varied clients."),
 "gateway": ("What is the core idea of the strangler fig pattern?", "Move features one at a time behind a router until the old system is empty", ["Rewrite the whole monolith privately and switch on release day", "Run two monoliths side by side and let users choose", "Replace the database first and the code later"], "You replace the monolith gradually, and the system keeps working throughout."),
 "micro": ("A new product is starting with a small team. What is the sensible default architecture?", "A well-structured monolith, split later for a concrete reason", ["Microservices from day one, so scaling is easy later", "One service per database table, for clean ownership", "Serverless functions for everything, to avoid servers"], "A modular monolith is faster to build and easier to run. Split a service out when a team, a scaling need or a technology demands it."),
 "eventdriven": ("Why use the outbox pattern when a service changes data and also publishes an event?", "The change and the event are saved in one transaction, so neither is lost", ["It makes events smaller and cheaper to send", "It lets the service skip the message broker", "It guarantees events arrive in exactly the order produced"], "Writing to the database and publishing separately can lose one of the two. The outbox row commits with the data and a relay publishes it afterwards."),
 "resil": ("Why add random jitter to retry delays?", "So many clients do not all retry at the same instant", ["So each retry is faster than the one before", "So failed requests are logged less often", "So the server can tell retries from new requests"], "Synchronised retries create a thundering herd that keeps a struggling service down. Jitter spreads them out."),
 "ratelimiter": ("What does a token bucket allow that a strict fixed rate does not?", "A short burst up to the bucket size, with the long-term rate still capped", ["Unlimited traffic while the bucket is full", "Different limits for every endpoint with no extra state", "Exact counting across many servers with no shared state"], "Unused tokens accumulate up to the capacity, so a brief burst passes while sustained traffic is limited to the refill rate."),
 "observe": ("One user request crosses five services and is slow. Which signal shows where the time went?", "A distributed trace of that request", ["The CPU metric of each service", "A log line from the first service", "The average latency on the main dashboard"], "A trace follows one request across services and shows the time spent in each hop. Logs say what happened and metrics say how much."),
 "slo": ("About how much downtime does a 99.9% SLO allow in a 30-day month?", "About 43 minutes", ["About 4 minutes", "About 8 minutes", "About 7 hours"], "0.1% of 30 days is about 43 minutes. A 99.99% SLO allows about 4 minutes."),
 "chaos": ("What should you define before injecting a failure into production?", "A steady-state metric, a hypothesis and a small blast radius", ["The largest failure the system could possibly suffer", "A company-wide freeze on deployments", "The failure list recommended by the tool vendor"], "You need to know what normal looks like, what you expect to happen, and how to limit the damage if you are wrong."),
 "dr": ("What does an RPO of 5 minutes mean?", "You can lose at most the last 5 minutes of data", ["Recovery must be complete within 5 minutes", "Backups must finish running within 5 minutes", "A failure must be detected within 5 minutes"], "RPO measures how much data you can lose, in time. RTO measures how long you can be down."),
 "auth": ("A user changes /orders/42 to /orders/43 in the address bar and sees another customer's order. What is the flaw?", "Missing object-level authorisation (an IDOR bug)", ["SQL injection in the order ID", "A weak password hashing algorithm", "Cross-site scripting in the order page"], "Logging in is not enough. Every request must check that the signed-in user owns the object being asked for."),
 "netsec": ("Where should a production database live?", "In a private subnet reachable only from the app tier", ["In a public subnet, protected by a strong password", "In the same subnet as the load balancer", "Anywhere, as long as the traffic uses TLS"], "Only the app tier needs to reach it, so keep it off the internet. TLS protects data in transit but does not shrink the attack surface."),
 "containers": ("What does a Kubernetes readiness probe decide?", "Whether the pod should receive traffic from its Service", ["Whether the container should be restarted", "Whether the node has enough memory for the pod", "Whether the image is the latest version"], "A pod that is not ready is removed from the Service until it passes. Restarts are the job of the liveness probe."),
 "iac": ("What does terraform plan do?", "Shows the changes it would make, without changing anything", ["Applies the changes after asking for confirmation", "Refreshes the state file by deleting stale resources", "Checks only the syntax of the configuration files"], "Plan is a preview so you can review before you apply."),
 "serverless": ("Which workload fits functions best?", "Resizing an image each time one is uploaded", ["A database that must stay running all day", "A job that runs for many hours without a break", "A game server holding long-lived connections"], "Short, event-driven and spiky work is ideal. Long-running or connection-heavy work fits servers or containers better."),
 "deploy": ("Why is it risky to rename a database column in the same deploy that ships new code?", "Old servers still running during the rollout would break", ["Databases cannot rename columns while the app is running", "A rename always takes the table offline for hours", "Renaming is slower than adding a column"], "Old and new versions overlap during a rollout. Use expand and contract so both versions work at every step."),
 "scale": ("Database reads dominate your load. What do you usually try first?", "Add indexes and caching, then read replicas", ["Shard the database across many servers", "Move to a different database engine", "Add more app servers behind the load balancer"], "Indexes and caches are cheap and effective. Sharding is a last resort, and more app servers do nothing for a busy database."),
 "streaming": ("A topic has 6 partitions and one consumer group. What is the most useful number of consumers in the group?", "Six, because each partition goes to one consumer", ["Sixty, because more consumers read faster", "One, because a group needs exactly one consumer", "Twelve, so each partition has two readers"], "A partition is read by one consumer in a group, so extra consumers sit idle."),
 "batch": ("Why is a columnar warehouse better than a row-based transactional database for analytics?", "A query reads only the columns it needs, and columns compress well", ["It has no schema, so any data can be loaded", "It stores less data because it drops old rows", "It builds an index on every column automatically"], "Analytics scans a few columns across many rows. Columnar storage reads just those columns."),
 "solid": ("A function with an if/elif chain that you edit for every new discount type breaks which principle?", "Open/closed: add behaviour by adding code, not by editing it", ["Liskov substitution: subtypes must replace their parents", "Interface segregation: interfaces should be small", "Dependency inversion: depend on abstractions"], "You should extend behaviour by adding new classes, such as a new discount, instead of modifying existing code."),
 "oop": ("In the object-modelling routine, what do the nouns in the requirements usually become?", "Classes, with the verbs becoming their methods", ["Methods, with the verbs becoming classes", "Design patterns, with the verbs becoming interfaces", "Database tables, with the verbs becoming columns"], "Nouns suggest entities (classes) and verbs suggest behaviour (methods)."),
 "patterns": ("A vending machine behaves differently when idle, holding money or dispensing. Which pattern fits?", "State: each state is an object with its own behaviour", ["Singleton: there is only one machine", "Decorator: wrap the machine with extra features", "Observer: the machine subscribes to coin events"], "When behaviour depends on the current state, model each state as an object."),
 "conc": ("Two servers try to book the same seat at the same moment. Which fix works across servers?", "A conditional update: set booked only where the seat is still free", ["A mutex inside the booking function", "A bigger server so requests finish sooner", "A thread-safe in-memory set of booked seats"], "In-process locks do not span machines. Let the database make the check-and-set one atomic step."),
 "parking": ("Two entry gates call park() at the same moment. What prevents double allocation?", "Making check-and-assign atomic with a lock or a row lock", ["Faster hardware, so requests rarely overlap", "Checking for a free spot twice before assigning", "Letting the exit gate fix duplicates afterwards"], "Check-then-assign is a race. It must happen as one indivisible step."),
 "lru": ("Why does an LRU cache use a doubly linked list instead of a singly linked one?", "A node can be unlinked in O(1) when you hold a pointer to it", ["It uses less memory per entry", "It keeps the entries sorted by key", "It lets two threads read at once"], "Removing a node from the middle needs its previous node. A doubly linked list stores that pointer."),
 "urlshort": ("Why choose a 302 redirect over a 301 for a link shortener?", "Every click passes through you, so you keep analytics and can change the target", ["302 is faster for users because browsers cache it", "302 is cached forever, which saves bandwidth", "301 is not allowed for links to other sites"], "Browsers cache 301 redirects, so later clicks bypass you and you cannot change where the link goes."),
 "chat": ("A phone resends a message after a timeout. How do you avoid showing it twice?", "The client creates a unique message ID and the server dedupes on it", ["The server ignores any message that arrives after a delay", "The server sorts by timestamp and drops equal ones", "The receiving phone compares the message texts"], "A stable ID makes the retry recognisable as the same message, whatever its text or timing."),
 "geo": ("Why search the neighbouring cells as well as the user's own cell?", "A closer point can sit just across the cell border", ["Cells are only accurate to a few kilometres", "Empty cells are slower to read than full ones", "Neighbouring cells keep copies of the same points"], "Cells cut space into pieces with hard borders, so the nearest point can be in the next cell."),
 "feed": ("Why do large feeds use a hybrid push and pull model?", "Pushing a celebrity's post to millions of feeds is too costly, so it is pulled at read time", ["Pulling is always faster, so pushing is only a backup", "Pushing removes the need for a feed cache", "It keeps every feed in sync with the follower graph"], "Push works for normal accounts. For huge accounts it is cheaper to merge their posts when a follower reads."),
 "ecommerce": ("Why return an order ID before the payment has finished?", "Checkout stays fast while slow payment and stock steps run in the background", ["It lets the shop skip payment for trusted customers", "It avoids storing the order in a database", "It guarantees that the payment will succeed"], "Decoupling keeps checkout fast and absorbs spikes. The order stays PENDING until the workers finish."),
 "notify": ("Why give each notification an idempotency key?", "A retry after a timeout cannot send the same message twice", ["It encrypts the message on its way to the provider", "It lets urgent messages jump the queue", "It makes the provider send the message faster"], "Retries are needed because providers fail, but a retry may repeat a message that did go through. The key lets the worker skip it."),
 "netflix": ("Why is video served from CDN caches near viewers rather than from one origin?", "One origin cannot supply terabits per second, and distance adds delay", ["Encoding is cheaper at the edge", "It avoids needing several bitrates", "Origin storage cannot hold video files"], "Millions of viewers at several megabits each add up to terabits per second, which no single origin can send."),
 "kvstore": ("A Dynamo-style store keeps 3 replicas of each key. Which write and read quorum sizes guarantee that a read sees the latest write?", "W = 2 and R = 2, because R + W exceeds N", ["W = 1 and R = 1, the fastest on both sides", "W = 2 and R = 1, because writes reach a majority", "W = 1 and R = 2, because reads check a majority"], "R + W must be greater than N. 2 + 2 = 4 is more than 3, but 2 + 1 = 3 and 1 + 2 = 3 are not."),
 "clickstream": ("What does a watermark do in stream processing?", "It sets how long to wait for late events before a window is closed", ["It marks events as duplicates so they are dropped", "It encrypts events between Kafka and the processor", "It limits how many events each window may hold"], "It tells the engine when it can stop expecting older events for a window."),
 "interview": ("What should you do first in a system design interview?", "Clarify requirements and scale before drawing anything", ["Draw the database schema, since data drives the design", "Pick a cloud provider and the main technologies", "Sketch the high-level boxes, then ask questions"], "Everything else depends on what is being built and how big it is."),
 "mvp": ("What should you build first for an MVP?", "One thin end-to-end slice of the core loop", ["Every feature, hidden behind flags", "The admin dashboard, so you can manage users", "The scalable architecture you will need later"], "A working vertical slice proves the idea and the architecture with the least code."),
 "backend": ("Where should database passwords and API keys live?", "In environment variables or a secrets manager, never in the repository", ["In a config file committed next to the code", "In the front-end code, encrypted with a key", "In the Dockerfile, so the image is self-contained"], "Anything committed to the repository or shipped to the browser should be treated as public."),
 "projects": ("What best shows that you finished a project?", "You can show a measured result or a working demo", ["You read all of the instructions", "You installed all of the tools", "You wrote down what you would build next"], "A number or a demo that shows the behaviour is the proof. Reading and setup are only the start."),
}

doc = json.loads(F.read_text())
ids = [l["id"] for l in doc["lessons"]]
assert set(ids) == set(Q), (set(ids) ^ set(Q))
slots = [i % 4 for i in range(len(ids))]
random.Random(11).shuffle(slots)
for l, pos in zip(doc["lessons"], slots):
    q, right, wrong, why = Q[l["id"]]
    opts = list(wrong)
    opts.insert(pos, right)
    l["quiz"] = {"q": q, "o": opts, "a": pos, "w": why}
F.write_text(json.dumps(doc, indent=1, ensure_ascii=False))
print("rewrote", len(ids))
